const first = $input.first().json || {};
const isWebhook = !!first.body;
const body = isWebhook ? (first.body || {}) : {};

// CONFIG — edit here (no n8n environment variables; blocked on some deployments)
const CONFIG = {
  githubApiBase: 'https://github.boschdevcloud.com/api/v3',
  file2ediApiBase: 'https://adv.bosch-homecomfort.com',
  owner: 'RSR1DY',
  repo: 'masterdata',
  defaultBranch: 'main',
  allowedBranches: ['main'],
};

const apiBase = String(body.githubApiBase || CONFIG.githubApiBase).replace(/\/$/, '');
const file2ediBase = String(
  body.file2ediApiBase || body.apiBase || CONFIG.file2ediApiBase
).replace(/\/$/, '');
const owner = String(body.owner || CONFIG.owner).trim();
const repo = String(body.repo || CONFIG.repo).trim();
const defaultBranch = CONFIG.defaultBranch;
const branch = String(body.branch || defaultBranch).trim();
const allowedBranches = Array.isArray(body.allowedBranches)
  ? body.allowedBranches.map((value) => String(value).trim()).filter(Boolean)
  : CONFIG.allowedBranches;

if (!allowedBranches.includes(branch)) {
  throw new Error(
    `Branche interdite: ${branch}. Branches autorisees: ${allowedBranches.join(', ')}`
  );
}

const encodePath = (path) =>
  String(path)
    .split('/')
    .map((part) => encodeURIComponent(part))
    .join('/');

const files = [
  {
    kind: 'customers',
    parquet: '10564_Customers.parquet',
    csv: '10564_Customers.csv',
  },
  {
    kind: 'partners',
    parquet: '10564_Partners.parquet',
    csv: '10564_Partners.csv',
  },
  {
    kind: 'materials',
    parquet: 'DB_Materials.parquet',
    csv: 'DB_Materials.csv',
  },
  {
    kind: 'salesorders',
    parquet: 'DB_Salesorder.parquet',
    csv: 'DB_Salesorder.csv',
  },
];

const runId = `${Date.now()}-${Math.random().toString(36).slice(2, 10)}`;
const reason = body.reason || (isWebhook ? 'manual_webhook' : 'scheduled');
const actor = body.actor || (isWebhook ? 'webhook' : 'n8n-schedule');

return files.map((file, sourceIndex) => {
  const parquetPath = encodePath(file.parquet);
  const csvPath = encodePath(file.csv);

  return {
    json: {
      runId,
      sourceIndex,
      syncKey: `${runId}:${file.kind}`,
      reason,
      actor,
      owner,
      repo,
      branch,
      kind: file.kind,
      parquet: file.parquet,
      csv: file.csv,
      file: file.parquet,
      format: 'parquet',
      rawParquetUrl:
        `${apiBase}/repos/${encodeURIComponent(owner)}/${encodeURIComponent(repo)}` +
        `/contents/${parquetPath}?ref=${encodeURIComponent(branch)}`,
      rawCsvUrl:
        `${apiBase}/repos/${encodeURIComponent(owner)}/${encodeURIComponent(repo)}` +
        `/contents/${csvPath}?ref=${encodeURIComponent(branch)}`,
      importUrl: `${file2ediBase}/api/masterdata/import`,
      reloadUrl: `${file2ediBase}/api/masterdata/reload-cache`,
      repoUrl: `https://github.boschdevcloud.com/${owner}/${repo}.git`,
    },
    pairedItem: {
      item: 0,
    },
  };
});

const listed = $('1. Lister fichiers').all();
const responses = $input.all();
const out = [];

for (let i = 0; i < responses.length; i++) {
  const source = (listed[i] && listed[i].json) || {};
  const item = responses[i] || {};
  const response = item.json || {};
  const statusCode = Number(response.statusCode || response.status || 0);

  const base = {
    ...source,
    statusCode,
    file: source.parquet,
    format: 'parquet',
    needCsv: false,
    ready: false,
    skip: false,
    ok: false,
  };

  if (statusCode === 404) {
    out.push({
      json: {
        ...base,
        needCsv: true,
        message: `Parquet absent, fallback CSV: ${source.parquet}`,
      },
      pairedItem: { item: i },
    });
    continue;
  }

  if (!(statusCode >= 200 && statusCode < 300)) {
    out.push({
      json: {
        ...base,
        skip: true,
        message: `Erreur GitHub Parquet HTTP ${statusCode || 'inconnu'}: ${source.parquet}`,
      },
      pairedItem: { item: i },
    });
    continue;
  }

  const binary = item.binary && item.binary.data;
  if (!binary) {
    out.push({
      json: {
        ...base,
        skip: true,
        message: `Reponse GitHub sans binaire: ${source.parquet}`,
      },
      pairedItem: { item: i },
    });
    continue;
  }

  let buffer;
  try {
    buffer = await this.helpers.getBinaryDataBuffer(i, 'data');
  } catch (error) {
    out.push({
      json: {
        ...base,
        skip: true,
        message: `Lecture binaire impossible: ${source.parquet} - ${error.message}`,
      },
      pairedItem: { item: i },
    });
    continue;
  }

  const size = buffer.length;
  const validParquet =
    size >= 8 &&
    buffer.subarray(0, 4).toString('ascii') === 'PAR1' &&
    buffer.subarray(size - 4).toString('ascii') === 'PAR1';

  if (!validParquet) {
    out.push({
      json: {
        ...base,
        size,
        skip: true,
        message: `Fichier Parquet invalide ou reponse d'erreur: ${source.parquet}`,
      },
      pairedItem: { item: i },
    });
    continue;
  }

  out.push({
    json: {
      ...base,
      size,
      ready: true,
      ok: true,
      message: `Parquet pret: ${source.parquet}`,
    },
    binary: {
      data: {
        ...binary,
        fileName: source.parquet,
        mimeType: 'application/octet-stream',
      },
    },
    pairedItem: { item: i },
  });
}

return out;

const source = $('4. Fallback CSV ?').item.json || {};
const response = $json || {};
const statusCode = Number(response.statusCode || response.status || 0);

const base = {
  ...source,
  statusCode,
  file: source.csv,
  format: 'csv',
  needCsv: false,
  ready: false,
  skip: false,
  ok: false,
};

if (!(statusCode >= 200 && statusCode < 300)) {
  return {
    json: {
      ...base,
      skip: true,
      message: `Erreur GitHub CSV HTTP ${statusCode || 'inconnu'}: ${source.csv}`,
    },
  };
}

const binary = $binary && $binary.data;
if (!binary) {
  return {
    json: {
      ...base,
      skip: true,
      message: `Reponse GitHub sans binaire: ${source.csv}`,
    },
  };
}

let buffer;
try {
  buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
} catch (error) {
  return {
    json: {
      ...base,
      skip: true,
      message: `Lecture binaire impossible: ${source.csv} - ${error.message}`,
    },
  };
}

if (!buffer.length) {
  return {
    json: {
      ...base,
      skip: true,
      message: `CSV vide: ${source.csv}`,
    },
  };
}

const prefix = buffer
  .subarray(0, Math.min(buffer.length, 512))
  .toString('utf8')
  .trimStart()
  .toLowerCase();

const looksLikeErrorPage =
  prefix.startsWith('<!doctype html') ||
  prefix.startsWith('<html') ||
  (prefix.startsWith('{') &&
    (prefix.includes('"message"') || prefix.includes('"error"')));

if (looksLikeErrorPage) {
  return {
    json: {
      ...base,
      size: buffer.length,
      skip: true,
      message: `Le contenu recu n'est pas un CSV valide: ${source.csv}`,
    },
  };
}

return {
  json: {
    ...base,
    size: buffer.length,
    ready: true,
    ok: true,
    message: `CSV pret: ${source.csv}`,
  },
  binary: {
    data: {
      ...binary,
      fileName: source.csv,
      mimeType: 'text/csv',
    },
  },
};

const source = $('8. Skip import ?').item.json || {};
const response = $json || {};
const statusCode = Number(response.statusCode || response.status || 0);
const body =
  response.body !== undefined && response.body !== null
    ? response.body
    : response;

const bodyObject =
  body && typeof body === 'object' && !Array.isArray(body)
    ? body
    : {};

const ok =
  statusCode >= 200 &&
  statusCode < 300 &&
  bodyObject.ok !== false &&
  bodyObject.status !== 'error' &&
  !bodyObject.error;

const message = ok
  ? String(bodyObject.message || 'Import OK')
  : String(
      bodyObject.message ||
      bodyObject.detail ||
      bodyObject.error ||
      `Import File2EDI HTTP ${statusCode || 'inconnu'}`
    );

return {
  json: {
    runId: source.runId,
    sourceIndex: source.sourceIndex,
    syncKey: source.syncKey,
    branch: source.branch,
    kind: source.kind,
    file: source.file,
    format: source.format,
    size: source.size,
    imported: ok,
    ok,
    rows: bodyObject.rows,
    statusCode,
    message,
  },
};

const expectedItems = $('1. Lister fichiers')
  .all()
  .map((item) => item.json || {})
  .sort((a, b) => Number(a.sourceIndex) - Number(b.sourceIndex));

const preparedItems = [];
try {
  for (const item of $('3. Evaluer Parquet').all()) {
    const row = item.json || {};
    // Items that need CSV fallback are handled by node 6, not here.
    if (row.needCsv === true) continue;
    preparedItems.push(row);
  }
} catch (eParquet) {}
try {
  for (const item of $('6. Evaluer CSV').all()) {
    preparedItems.push(item.json || {});
  }
} catch (eCsv) {}

const importItems = $input.all().map((item) => item.json || {});

const preparedByKind = new Map(
  preparedItems.map((item) => [item.kind, item])
);

const importsByKind = new Map(
  importItems.map((item) => [item.kind, item])
);

const files = [];
let synced = 0;
let failed = 0;

for (const expected of expectedItems) {
  const prepared = preparedByKind.get(expected.kind);

  if (!prepared) {
    failed += 1;
    files.push({
      kind: expected.kind,
      file: expected.parquet,
      ok: false,
      message: 'Fichier prepare absent du flux',
    });
    continue;
  }

  if (prepared.skip) {
    failed += 1;
    files.push({
      kind: prepared.kind,
      file: prepared.file,
      format: prepared.format,
      ok: false,
      message: String(prepared.message || 'Preparation ignoree'),
    });
    continue;
  }

  const imported = importsByKind.get(prepared.kind);
  if (!imported) {
    failed += 1;
    files.push({
      kind: prepared.kind,
      file: prepared.file,
      format: prepared.format,
      ok: false,
      message: 'Resultat import absent',
    });
    continue;
  }

  if (imported.ok) {
    synced += 1;
    files.push({
      kind: prepared.kind,
      file: prepared.file,
      format: prepared.format,
      size: prepared.size,
      ok: true,
      rows: imported.rows,
      statusCode: imported.statusCode,
      message: imported.message || 'OK',
    });
  } else {
    failed += 1;
    files.push({
      kind: prepared.kind,
      file: prepared.file,
      format: prepared.format,
      size: prepared.size,
      ok: false,
      statusCode: imported.statusCode,
      message: imported.message || 'Import en echec',
    });
  }
}

const expected = expectedItems.length;
const ok = expected === 4 && synced === expected && failed === 0;

const okNames = files
  .filter((file) => file.ok)
  .map((file) => file.file)
  .join(', ');

const koNames = files
  .filter((file) => !file.ok)
  .map((file) => `${file.file}: ${file.message}`)
  .join(' | ');

const first = expectedItems[0] || {};

return [
  {
    json: {
      ok,
      runId: first.runId,
      synced,
      failed,
      expected,
      files,
      source: 'n8n-github-raw',
      owner: first.owner,
      repository: first.repo,
      branch: first.branch,
      repo: first.repoUrl,
      message: ok
        ? `Sync masterdata OK - ${synced}/${expected}: ${okNames}`
        : `Sync masterdata partielle - ${synced}/${expected} OK (${okNames || 'aucun'}), ${failed} echec(s) (${koNames || 'resultat incomplet'})`,
    },
  },
];

const expectedItems = $('1. Lister fichiers')
  .all()
  .map((item) => item.json || {})
  .sort((a, b) => Number(a.sourceIndex) - Number(b.sourceIndex));

const preparedItems = [];
try {
  for (const item of $('3. Evaluer Parquet').all()) {
    const row = item.json || {};
    // Items that need CSV fallback are handled by node 6, not here.
    if (row.needCsv === true) continue;
    preparedItems.push(row);
  }
} catch (eParquet) {}
try {
  for (const item of $('6. Evaluer CSV').all()) {
    preparedItems.push(item.json || {});
  }
} catch (eCsv) {}

if (preparedItems.some((item) => !item.skip)) {
  return [];
}

const preparedByKind = new Map(
  preparedItems.map((item) => [item.kind, item])
);

const files = expectedItems.map((expected) => {
  const prepared = preparedByKind.get(expected.kind);
  return {
    kind: expected.kind,
    file: prepared?.file || expected.parquet,
    format: prepared?.format,
    ok: false,
    message: String(
      prepared?.message || 'Aucun fichier disponible pour import'
    ),
  };
});

const first = expectedItems[0] || {};
const failed = files.length;
const details = files
  .map((file) => `${file.file}: ${file.message}`)
  .join(' | ');

return [
  {
    json: {
      ok: false,
      runId: first.runId,
      synced: 0,
      failed,
      expected: expectedItems.length,
      files,
      source: 'n8n-github-raw',
      owner: first.owner,
      repository: first.repo,
      branch: first.branch,
      repo: first.repoUrl,
      message: `Sync masterdata en echec - 0/${expectedItems.length} OK, ${failed} echec(s) (${details})`,
    },
  },
];

let aggregate = {};
try {
  aggregate = $('11. Aggregator').first().json || {};
} catch (error) {
  try {
    aggregate = $('11b. Skip-only agg').first().json || {};
  } catch (innerError) {}
}

const response = $json || {};
const statusCode = Number(response.statusCode || response.status || 0);
const body =
  response.body !== undefined && response.body !== null
    ? response.body
    : response;

const bodyObject =
  body && typeof body === 'object' && !Array.isArray(body)
    ? body
    : {};

const reloadOk =
  statusCode >= 200 &&
  statusCode < 300 &&
  bodyObject.ok !== false &&
  bodyObject.status !== 'error' &&
  !bodyObject.error;

return [
  {
    json: {
      ...aggregate,
      ok: aggregate.ok === true && reloadOk,
      cache_reloaded: reloadOk,
      cache_status_code: statusCode,
      message:
        (aggregate.message || 'Sync masterdata') +
        (reloadOk
          ? ' - cache recharge'
          : ` - reload-cache en echec HTTP ${statusCode || 'inconnu'}`),
    },
  },
];

const aggregate = $json || {};

return [
  {
    json: {
      ...aggregate,
      ok: false,
      cache_reloaded: false,
      message:
        (aggregate.message || 'Sync masterdata en echec') +
        ' - cache non recharge car la synchronisation est incomplete',
    },
  },
];
